// Original playable adaptation of Fellowship's fields → wooded road → ferry.
export const ROAD_STEPS=Object.freeze(['fields','meeting','rider','escape','crossing','bree']);
export const ROAD_POINTS=Object.freeze({entry:{x:-27,z:-36},meeting:{x:-24,z:-19},cover:{x:-14,z:0},ferry:{x:10,z:23},landing:{x:10,z:35},gate:{x:10,z:45}});
export const freshRoad=()=>({step:'fields'});
export function restoreRoad(value,phase){return phase==='roads'&&ROAD_STEPS.includes(value?.step)?{step:value.step}:freshRoad();}
export const nearRoadPoint=(p,target,radius=2.5)=>Number.isFinite(p?.x)&&Number.isFinite(p?.z)&&Math.hypot(p.x-target.x,p.z-target.z)<radius;
export function advanceRoad(road,action,p){
 const transitions={meet:['fields','meeting',ROAD_POINTS.meeting],join:['meeting','rider',ROAD_POINTS.meeting],hide:['rider','escape',ROAD_POINTS.cover],board:['escape','crossing',ROAD_POINTS.ferry],land:['crossing','bree',ROAD_POINTS.landing]};
 const t=transitions[action];if(!t||road.step!==t[0]||!nearRoadPoint(p,t[2],action==='hide'?2.2:3))return false;road.step=t[1];return true;
}
export function roadObjective(road){return ({fields:'اتبع درب الحقول؛ سام معك. اقترب من السياج عند ميري وبيبين.',meeting:'تحدّث مع ميري وبيبين قبل مواصلة الطريق.',rider:'فارس أسود يفتّش الدرب. اختبئ في فجوة الجذور وابقَ ساكنًا.',escape:'مرّ الفارس. اتبع الدرب إلى عبّارة باكِلبري عند النهر.',crossing:'ابقَ على العبّارة؛ الأصدقاء يدفعونها نحو الضفة الأخرى.',bree:'عبرت برانديواين مع الأصدقاء. الطريق إلى بوابة بري في الشمال.'})[road.step];}
export function coverProgress(previous,dt,p,moving,paused){if(paused)return previous;return nearRoadPoint(p,ROAD_POINTS.cover,2.2)&&!moving?Math.min(6,previous+Math.max(0,Math.min(.2,dt))):0;}
export function drawRoadMap(canvas,p,road){const c=canvas.getContext('2d');if(!c)return;const w=canvas.width,h=canvas.height,project=(x,z)=>({x:30+(x+49)/98*(w-60),y:30+(52-z)/99*(h-60)});c.clearRect(0,0,w,h);c.fillStyle='#d9dbb5';c.fillRect(0,0,w,h);c.fillStyle='#719596';const a=project(-49,34),b=project(49,25);c.fillRect(a.x,a.y,b.x-a.x,b.y-a.y);c.strokeStyle='#ac9467';c.lineWidth=10;c.beginPath();[P.entry,P.meeting,{x:-13,z:-9},{x:-7,z:1},{x:0,z:10},P.ferry].forEach((v,i)=>{const q=project(v.x,v.z);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);});c.stroke();c.beginPath();for(const [i,v]of [P.landing,P.gate].entries()){const q=project(v.x,v.z);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);}c.stroke();c.font='bold 15px Tahoma';c.textAlign='center';for(const [name,v]of [['الحقول',P.entry],['ميري وبيبين',P.meeting],['الجذور',P.cover],['عبّارة باكِلبري',P.ferry],['الضفة الشرقية',P.landing],['بوابة بري',P.gate]]){const q=project(v.x,v.z);c.fillStyle='#49543d';c.beginPath();c.arc(q.x,q.y,5,0,Math.PI*2);c.fill();c.fillText(name,q.x,q.y-12);}if(p){const q=project(p.x,p.z);c.fillStyle='#1d4e74';c.beginPath();c.arc(q.x,q.y,9,0,Math.PI*2);c.fill();c.strokeStyle='#fff9d5';c.lineWidth=3;c.stroke();}c.font='12px Tahoma';c.fillStyle='#49543d';c.fillText('خريطة لعب مختصرة · المواقع مستوحاة من القصة',w/2,h-12);}
